#!/bin/sh
# Generated by `go run ./cmd/pubsub-topology` (in backend/) from
# backend/internal/events/pubsub/topology.go. DO NOT EDIT: change the Go and regenerate.
#
# Creates the Pub/Sub topology on the emulator: the topics, the push subscriptions to
# compose's services (http://<service>:8080<path>) with the retry and dead-letter policy
# Terraform sets (infra/gcp/pubsub.tf), and the dead-letter hold subscriptions (pull).
# Idempotent: what exists already (HTTP 409) is kept as it is, so a rerun on a running
# emulator is fine. The emulator checks no IAM and no OIDC token.
#
# Usage: PUBSUB_EMULATOR_HOST=pubsub:8085 [GCP_PROJECT=ryft-local] sh init.sh
set -eu

: "${PUBSUB_EMULATOR_HOST:?set PUBSUB_EMULATOR_HOST to the emulator's host:port}"
: "${GCP_PROJECT:=ryft-local}"
base="http://${PUBSUB_EMULATOR_HOST}/v1/projects/${GCP_PROJECT}"

# Wait up to 60 s for the emulator to answer.
i=0
until curl -s -o /dev/null "http://${PUBSUB_EMULATOR_HOST}/"; do
  i=$((i + 1))
  if [ "$i" -ge 60 ]; then
    echo "init.sh: the emulator at ${PUBSUB_EMULATOR_HOST} does not answer" >&2
    exit 1
  fi
  sleep 1
done

# put <path> <json>: 200 created, 409 exists already; anything else stops the script.
put() {
  code=$(curl -s -o /dev/null -w '%{http_code}' -X PUT -H 'Content-Type: application/json' --data "$2" "${base}/$1") || code=000
  case "$code" in
    200) echo "created $1" ;;
    409) echo "exists  $1" ;;
    *) echo "init.sh: PUT $1 answered HTTP $code" >&2; exit 1 ;;
  esac
}

topic() {
  put "topics/$1" '{}'
}

# push <subscription> <topic> <endpoint> <ordered> <ack deadline s> <retention s> [<dead-letter topic>]
push() {
  dlq=""
  if [ -n "${7:-}" ]; then
    dlq=$(printf ',"deadLetterPolicy":{"deadLetterTopic":"projects/%s/topics/%s","maxDeliveryAttempts":20}' "$GCP_PROJECT" "$7")
  fi
  put "subscriptions/$1" "$(printf '{"topic":"projects/%s/topics/%s","pushConfig":{"pushEndpoint":"%s"},"enableMessageOrdering":%s,"ackDeadlineSeconds":%s,"messageRetentionDuration":"%ss","retryPolicy":{"minimumBackoff":"10s","maximumBackoff":"600s"}%s}' \
    "$GCP_PROJECT" "$2" "$3" "$4" "$5" "$6" "$dlq")"
}

# hold <subscription> <topic> <retention s>: a pull subscription.
hold() {
  put "subscriptions/$1" "$(printf '{"topic":"projects/%s/topics/%s","ackDeadlineSeconds":60,"messageRetentionDuration":"%ss"}' \
    "$GCP_PROJECT" "$2" "$3")"
}

topic ryft-dlq-notify
topic ryft-dlq-scoring
topic ryft-ingested
topic ryft-notify-wait
topic ryft-refresh
topic ryft-scored
topic ryft-session-completed
topic ryft-session-scored
topic ryft-tick

push notify-refresh ryft-refresh http://notify:8080/push/refresh false 60 604800 ryft-dlq-notify
push notify-scored ryft-scored http://notify:8080/push/scored false 60 604800 ryft-dlq-notify
push notify-session-scored ryft-session-scored http://notify:8080/push/session.scored false 60 604800 ryft-dlq-notify
push notify-wait ryft-notify-wait http://notify:8080/push/wait false 60 604800 ryft-dlq-notify
push scoring-ingested ryft-ingested http://scoring:8080/push/ingested true 300 604800 ryft-dlq-scoring
push scoring-session-completed ryft-session-completed http://scoring:8080/push/session.completed true 300 604800 ryft-dlq-scoring
push tick-api ryft-tick http://api:8080/internal/tick false 600 600
push tick-ingest ryft-tick http://ingest:8080/internal/tick false 600 600
push tick-notify ryft-tick http://notify:8080/internal/tick false 600 600
push tick-scoring ryft-tick http://scoring:8080/internal/tick false 600 600

hold dlq-notify-hold ryft-dlq-notify 1209600
hold dlq-scoring-hold ryft-dlq-scoring 1209600
